using Fallout.Common.CI.GitHubActions;
using Fallout.Components;

// .github/workflows/build.yml is GENERATED from this attribute and regenerated by every build -
// change the attribute, never the YAML (AGENTS.md hard rule 2). Same for marten-latest.yml,
// publish.yml and release.yml below: all four of this repository's workflows are generated, and none
// of them is hand-written.
//
// One Linux job. FetchDepth = 0 because the changelog-driven version and GitRepository want the full
// history. Test pulls in Browsers (Build.Browsers.cs), which installs Chromium on CI, so the browser
// suite really runs on every push and pull request rather than skipping itself into a green tick.
//
// CacheIncludePatterns replaces Fallout's default of [".fallout/temp", "~/.nuget/packages"] because
// ~/.cache/ms-playwright has to be in it: a Chromium download is ~150 MB and dwarfs everything else
// this job does. .fallout/temp is deliberately not carried over - it holds downloaded tooling this
// repository does not use, and caching it would only make the key harder to reason about.
[GitHubActions(
    "build",
    GitHubActionsImage.UbuntuLatest,
    FetchDepth = 0,
    OnPushBranches = ["main"],
    OnPullRequestBranches = ["main"],
    ConcurrencyGroup = "${{ github.workflow }}-${{ github.ref }}",
    ConcurrencyCancelInProgress = true,
    CacheIncludePatterns = ["~/.nuget/packages", "~/.cache/ms-playwright"],
    InvokedTargets = [nameof(ITest.Test)],
    PublishArtifacts = true,
    // Said out loud rather than left to GitHub's repository default, which is configurable and may be
    // read-write. This job only reads the source; it must never be able to write to the repository, and
    // naming one read permission makes every other permission `none` for the run. A convention test
    // asserts it, and asserts that this file cannot mint a nuget.org key either.
    ReadPermissions = [GitHubActionsPermissions.Contents])]
// .github/workflows/marten-latest.yml - both suites again, at the newest Marten 9.x CI tests.
//
// build.yml tests the floor the package ships with; almost no host runs it. This runs the same
// `dotnet fallout Test` with MARTEN_VERSION=latest, which Fallout binds to the MartenVersion parameter
// (Build.Marten.cs) and resolves to MartenStudioMartenLatest in Directory.Packages.props - an exact
// version, bumped deliberately in a pull request of its own, never a floating 9.*, so main cannot go
// red because Marten shipped. The env value names the property rather than the version so that a bump
// is one edit to Directory.Packages.props and nothing here.
//
// A workflow of its own rather than a second job in build.yml: a [GitHubActions] attribute makes one
// job per image and every job runs the same command line, and a separate check makes "red at the
// latest Marten" and "red at the floor" two different answers on a pull request. Same triggers,
// concurrency and read-only permission as build.yml; it never packs and never publishes - Pack refuses
// any Marten but the floor anyway - and it cannot mint a key, because it is not the file the nuget.org
// policy names (a convention test asserts both).
//
// CacheKeyFiles adds this workflow file to the default three so its cache key differs from
// build.yml's. Without it the two would share one key, whichever finished first would save it, and
// the other would restore a cache missing its own Marten's packages on every run - actions/cache
// never overwrites an existing key.
[GitHubActions(
    "marten-latest",
    GitHubActionsImage.UbuntuLatest,
    FetchDepth = 0,
    OnPushBranches = ["main"],
    OnPullRequestBranches = ["main"],
    ConcurrencyGroup = "${{ github.workflow }}-${{ github.ref }}",
    ConcurrencyCancelInProgress = true,
    CacheIncludePatterns = ["~/.nuget/packages", "~/.cache/ms-playwright"],
    CacheKeyFiles = ["**/global.json", "**/*.csproj", "**/Directory.Packages.props", ".github/workflows/marten-latest.yml"],
    InvokedTargets = [nameof(ITest.Test)],
    PublishArtifacts = true,
    Env = ["MARTEN_VERSION: latest"],
    ReadPermissions = [GitHubActionsPermissions.Contents])]
// .github/workflows/publish.yml - the nuget.org leg (D15).
//
// It lives in its own workflow file because a nuget.org trusted publishing policy is scoped by
// workflow *file name* and the nuget.org UI offers no branch or tag filter. Keeping it out of
// build.yml is what stops an ordinary push from running a workflow that could mint a publishing key:
// only this file can, and only a v*.*.* tag can trigger it.
//
// No OnPushIncludePaths/ExcludePaths: a path filter alongside `tags:` evaluates over the tag commit's
// diff and can silently skip the release run. One Ubuntu job, because more jobs would mean more OIDC
// exchanges racing for the same one-key-per-30s rate limit.
//
// CacheKeyFiles = [] switches the cache off for this job entirely. A release must not be able to
// differ from a clean build because of something a previous run left behind.
[GitHubActions(
    "publish",
    GitHubActionsImage.UbuntuLatest,
    FetchDepth = 0,
    OnPushTags = ["v*.*.*"],
    CacheKeyFiles = [],
    InvokedTargets = [nameof(ICompile.Compile), nameof(ITest.Test), nameof(Pack), nameof(Publish)],
    PublishArtifacts = true,
    // The nuget.org profile name that created the trusted publishing policy. Public information and
    // deliberately not a secret - it goes verbatim into the token-exchange request body, and a
    // secret would be masked out of exactly the error message that names it.
    Env = ["NUGET_USER: lahma"],
    EnvironmentName = "nuget",
    ReadPermissions = [GitHubActionsPermissions.Contents],
    WritePermissions = [GitHubActionsPermissions.IdToken])]
// .github/workflows/release.yml - the GitHub Release, cut from the same v*.*.* tag as publish.yml but
// as a separate, independent workflow.
//
// Separate because of what each one is allowed to hold. publish.yml can mint a nuget.org key and must
// therefore never also hold `contents: write`; release.yml writes the repository's releases and must
// therefore never be the file a publishing policy names. Neither depends on the other, so a nuget.org
// outage cannot hold up the release notes and a release-API hiccup cannot hold up the package.
//
// EnableGitHubToken is what puts GITHUB_TOKEN on the run step - ICreateGitHubRelease authenticates the
// GitHub API with it. Verified in the generated YAML (a convention test asserts both halves), because
// the failure mode is a workflow that runs happily and 401s at the one step that matters.
//
// PublishArtifacts = false: this job produces no build output worth keeping - the release body comes
// from artifacts/release-notes.md, which the target writes and reads in the same run.
[GitHubActions(
    "release",
    GitHubActionsImage.UbuntuLatest,
    FetchDepth = 0,
    OnPushTags = ["v*.*.*"],
    CacheKeyFiles = [],
    InvokedTargets = [nameof(ICreateGitHubRelease.CreateGitHubRelease)],
    PublishArtifacts = false,
    EnableGitHubToken = true,
    WritePermissions = [GitHubActionsPermissions.Contents])]
partial class Build
{
}
